use serde_json::Value;
#[test]fn rust_and_js_shared_canonical_envelope_and_economic_slot_vectors(){let v:Value=serde_json::from_str(include_str!("vectors/evidence-manifest-v1.json")).unwrap();for vector in v["vectors"].as_array().unwrap(){let m=&vector["manifest"];assert_eq!(flypow::evidence_manifest::digest(m).unwrap(),vector["root"]);let slot=flypow_economic_core::EconomicSlotKey{genesis_hash:m["genesisHash"].as_str().unwrap().into(),program_id:m["programId"].as_str().unwrap().into(),economic_task_id:m["economicTaskId"].as_str().unwrap().into(),kind:m["kind"].as_str().unwrap().into(),unit_id:m["unitId"].as_str().unwrap().into()};assert_eq!(slot.canonical().unwrap(),vector["slotKey"]);let mut leaked=m.clone();leaked["privatePayload"]=serde_json::json!({"salt":"must never publish"});assert!(flypow::evidence_manifest::digest(&leaked).is_err());}}
